<script setup>
import { computed, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowLeft, ArrowRight, Eye, EyeOff, Heart, Sparkles, ShieldCheck } from 'lucide-vue-next'
import BrandLogo from '../components/BrandLogo.vue'
import { useAppStore } from '../stores/app'
const route=useRoute(),router=useRouter(),store=useAppStore(),isRegister=computed(()=>route.path==='/register')
const form=reactive({name:'',email:'',password:'',confirm:''}),error=ref(''),busy=ref(false),show=ref(false)
watch(isRegister,()=>{error.value='';form.password='';form.confirm=''})
async function submit(){error.value='';if(isRegister.value&&form.password!==form.confirm){error.value='Пароли не совпадают.';return}busy.value=true;try{await store.authenticate(isRegister.value?'register':'login',form);const redirect=route.query.redirect;router.push(typeof redirect==='string'&&redirect.startsWith('/app')?redirect:'/app')}catch(e){error.value=e.message}finally{busy.value=false}}
async function demo(){busy.value=true;error.value='';try{await store.demo();router.push('/app')}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><div class="auth-page"><aside class="auth-art"><BrandLogo light/><div class="auth-art-content"><span class="eyebrow">СОЗДАНО ДЛЯ БЛАГОДАРНОСТИ</span><h1>Хороший сервис.<br>Искреннее<br><em>«спасибо».</em></h1><p>Помогаем гостям благодарить,<br>а командам — чувствовать свою ценность.</p><div class="auth-thanks"><span class="heart-tile"><Heart :size="30"/></span><div><strong>+ 500 ₽</strong><span>Ещё один повод улыбнуться</span></div><Sparkles :size="25"/></div></div><div class="auth-art-footer"><span>Чаевые без наличных. Забота без границ.</span><span>✳</span></div></aside><main class="auth-main"><RouterLink to="/" class="text-link auth-back"><ArrowLeft :size="17"/>На главную</RouterLink><div class="auth-form-wrap"><div class="mobile-only"><BrandLogo/></div><div class="eyebrow">{{ isRegister?'НОВАЯ ГЛАВА ДЛЯ ВАШЕЙ КОМАНДЫ':'РАДЫ ВАС ВИДЕТЬ' }}</div><h1>{{ isRegister?'Начнём с вашего ресторана':'С возвращением' }}<span class="heading-dot">.</span></h1><p class="muted">{{ isRegister?'Создайте аккаунт и принимайте первые благодарности.':'Войдите, чтобы увидеть, как прошёл день команды.' }}</p><form class="form-stack" @submit.prevent="submit"><label v-if="isRegister">Название ресторана<input v-model="form.name" required minlength="2" maxlength="100" autocomplete="organization" placeholder="Вкус-Сервис"></label><label>Электронная почта<input v-model="form.email" required type="email" autocomplete="email" placeholder="you@restaurant.ru"></label><label>Пароль<div class="password-input"><input v-model="form.password" required :minlength="isRegister?8:1" :type="show?'text':'password'" :autocomplete="isRegister?'new-password':'current-password'" :placeholder="isRegister?'Не менее 8 символов':'Введите пароль'"><button class="icon-btn" type="button" @click="show=!show" :aria-label="show?'Скрыть пароль':'Показать пароль'"><component :is="show?EyeOff:Eye" :size="18"/></button></div></label><label v-if="isRegister">Повторите пароль<input v-model="form.confirm" required minlength="8" type="password" autocomplete="new-password" placeholder="Ещё раз для уверенности"></label><p class="error-text" v-if="error" role="alert">{{ error }}</p><button class="btn btn-primary" :disabled="busy"><span v-if="busy" class="spinner"></span>{{ busy?'Подождите…':isRegister?'Создать аккаунт':'Войти в кабинет' }}<ArrowRight :size="18"/></button></form><div class="or-divider"><span></span>или познакомьтесь с сервисом<span></span></div><button class="btn btn-outline full" :disabled="busy" @click="demo"><Sparkles :size="17"/>Войти в демо-кабинет</button><p class="auth-switch">{{ isRegister?'Уже есть аккаунт?':'Ещё нет аккаунта?' }} <RouterLink :to="isRegister?'/login':'/register'">{{ isRegister?'Войти':'Зарегистрироваться' }}</RouterLink></p><p class="demo-disclaimer"><ShieldCheck :size="16"/>Это прототип: данные хранятся в вашем браузере.<br>Используйте вымышленные данные и тестовый пароль.</p></div><span class="auth-copyright">© {{ new Date().getFullYear() }} Tipro</span></main></div></template>
